function tr(s,inner){var k=norm(s);if(!k)return null;var e=D[k];if(e!==undefined)return e;var dot=k.match(/^(.*?)([.:!?…]+)$/);if(dot&&D[dot[1]]!==undefined)return D[dot[1]]+dot[2];
 for(var i=0;i<PT.length;i++){if(PT[i][0].test(k))return k.replace(PT[i][0],PT[i][1])}
 for(var j=0;j<PF.length;j++){var m=k.match(PF[j][0]);if(m){var r=PF[j][1](m);if(r)return r}}
 var sp=k.split(/(\s+[—–·|]\s+)/);if(sp.length>1){var o="";for(var q=0;q<sp.length;q++){if(q%2){o+=sp[q];continue}var x=part(sp[q]);if(x===null)return null;o+=x}return o}
 return null}
function doText(n){var p=n.parentNode;if(!p||SKIP[p.nodeName]||(p.closest&&p.closest("[data-no-i18n]")))return;var s=n.data,o=T.get(n);
 if(L==="en"){if(o&&s===o.en)return;var e=tr(s);if(e===null){if(o)T.delete(n);return}var v=s.match(/^\s*/)[0]+e+s.match(/\s*$/)[0];T.set(n,{vi:s,en:v});n.data=v}
 else if(o){if(s===o.en)n.data=o.vi;T.delete(n)}}
function doEl(el){var m=A.get(el)||{};for(var i=0;i<ATTR.length;i++){var a=ATTR[i];if(!el.hasAttribute(a))continue;var s=el.getAttribute(a),o=m[a];
 if(L==="en"){if(o&&s===o.en)continue;var e=tr(s);if(e===null)continue;m[a]={vi:s,en:e};el.setAttribute(a,e)}else if(o){if(s===o.en)el.setAttribute(a,o.vi);delete m[a]}}A.set(el,m)}
function doPhrase(n){var f=n.parentNode&&n.parentNode.closest&&n.parentNode.closest(".fxw");if(!f||!f.parentNode)return false;
 var run=[f],x=f.previousSibling;while(x){if(x.nodeType===3&&!x.data.trim()){x=x.previousSibling;continue}if(x.nodeType===1&&x.classList.contains("fxw")){run.unshift(x);x=x.previousSibling;continue}break}
 x=f.nextSibling;while(x){if(x.nodeType===3&&!x.data.trim()){x=x.nextSibling;continue}if(x.nodeType===1&&x.classList.contains("fxw")){run.push(x);x=x.nextSibling;continue}break}
 var txt=norm(run.map(function(r){return r.textContent}).join(" "));var e=tr(txt,1);if(e===null)return false;
 run.forEach(function(r,i){var w=document.createTreeWalker(r,4,null),y,first=(i===0);while(y=w.nextNode()){if(!y.data.trim())continue;var v=first?e:"";T.set(y,{vi:y.data,en:v});y.data=v;first=false}});return true}
function doGroup(n){if(T.get(n))return;if(doPhrase(n))return;var a=n.parentNode;for(var d=0;d<5&&a&&a!==document.body;d++,a=a.parentNode){if(a.nodeType!==1)break;var k=norm(a.textContent||"");if(k.length>600)break;var e=D[k];if(e===undefined)continue;
 var w=document.createTreeWalker(a,4,null),x,first=1;while(x=w.nextNode()){if(!x.data.trim())continue;var v=first?e:"";T.set(x,{vi:x.data,en:v});x.data=v;first=0}return}}
function walk(root){if(!root)return;if(root.nodeType===3){doText(root);return}if(root.nodeType!==1&&root.nodeType!==9&&root.nodeType!==11)return;if(root.nodeType===1){if(SKIP[root.nodeName])return;doEl(root)}
 var w=document.createTreeWalker(root,4,null),n,left=[];while(n=w.nextNode()){doText(n);if(L==="en"&&!T.get(n)&&VNR.test(n.data))left.push(n)}for(var z=0;z<left.length;z++)doGroup(left[z]);
 if(root.querySelectorAll){var els=root.querySelectorAll("[placeholder],[aria-label],[alt],[title]");for(var i=0;i<els.length;i++)doEl(els[i])}}
var tt0=null;function doTitle(){var t=document.title;if(L==="en"){var e=tr(t);if(e!==null&&e!==t){tt0=t;document.title=e}}else if(tt0!==null){var e2=tr(tt0);if(t===e2)document.title=tt0;tt0=null}}
var q=[],sch=0;function flush(){sch=0;var a=q;q=[];for(var i=0;i<a.length;i++)walk(a[i]);doTitle()}
function push(n){q.push(n);if(!sch)sch=requestAnimationFrame(flush)}
var mo=new MutationObserver(function(ms){if(L!=="en")return;for(var i=0;i<ms.length;i++){var m=ms[i];if(m.type==="characterData")push(m.target);else if(m.type==="attributes")push(m.target);else for(var j=0;j<m.addedNodes.length;j++)push(m.addedNodes[j])}});
function start(){mo.observe(document.documentElement,{childList:true,subtree:true,characterData:true,attributes:true,attributeFilter:ATTR});document.documentElement.lang=L==="en"?"en":"vi";walk(document.body);doTitle();syncCareersToggle()}
function setLang(l){try{localStorage.setItem(K,l)}catch(e){}apply()}
